(()=>{'use strict';const KEY='launchkit-v4-demo',BOOK='launchkit-v4-bookings',EVENT='launchkit-v4-events';const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const valid=x=>{try{const u=new URL(x);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};let data=null;const logoSymbol={instagram:'◎',snapchat:'👻',tiktok:'♪'};const navs=[['home','الرئيسية'],['services','الخدمات والمنتجات'],['gallery','المعرض'],['book','المواعيد'],['contact','تواصل معنا']];const f=k=>data?.fields?.[k]||'';const hasBookings=()=>f('category')==='booking';const maps=()=>valid(f('map'));function links(){return[['instagram','إنستغرام'],['snapchat','سناب شات'],['tiktok','تيك توك']].filter(([k])=>valid(f(k))).map(([k,label])=>`<a href="${esc(valid(f(k)))}" target="_blank" rel="noopener noreferrer"><span aria-hidden="true">${logoSymbol[k]}</span> ${label}</a>`).join('')};function contact(){const phone=f('phone').replace(/[^+0-9]/g,''),wh=f('whatsapp').replace(/\D/g,'');const wa=wh.startsWith('0')?'966'+wh.slice(1):wh;return `<div class="contacts">${phone?`<a class="pill" href="tel:${esc(phone)}">☎ اتصل بنا</a>`:''}${wa?`<a class="pill" href="https://wa.me/${esc(wa)}" target="_blank" rel="noopener noreferrer">واتساب</a>`:''}${f('email')?`<a class="pill" href="mailto:${esc(f('email'))}">البريد الإلكتروني</a>`:''}</div><div class="social">${links()}</div>`};function grid(){return(data.items||[]).map(it=>`<article class="card"><h3>${esc(it.name)}</h3><p>${esc(it.description)}</p><p class="price">${esc(it.price||'0')} ر.س</p>${valid(it.link)?`<a class="pill" href="${esc(valid(it.link))}" target="_blank" rel="noopener noreferrer">تفاصيل / شراء</a>`:''}</article>`).join('')||'<div class="empty">لم تُضف خدمات أو منتجات بعد.</div>'};function gallery(){return data.gallery?.length?`<div class="gallery">${data.gallery.map((src,i)=>`<img src="${src}" alt="صورة معرض ${i+1}" loading="lazy">`).join('')}</div>`:'<div class="empty">لم تُضف صور للمعرض بعد.</div>'}function mapView(){return maps()?`<div class="mapbox"><p>اضغط لفتح موقع النشاط على خرائط Google. قد تتطلب معاينة خريطة مضمّنة رابط تضمين مخصصاً.</p><a href="${esc(maps())}" class="pill" target="_blank" rel="noopener noreferrer">↗ عرض الموقع على خرائط Google</a></div>`:'<p class="hint">لم يحدد النشاط عنواناً على الخرائط.</p>'}function booking(){if(!hasBookings())return'';const options=(data.items||[]).map((i,n)=>`<option value="${n}">${esc(i.name)} — ${esc(i.price||0)} ر.س</option>`).join('');return `<section class="section" id="book"><h2>احجزي موعدك</h2><p>اختاري الخدمة والموعد المناسب. تُحفظ الطلبات في نسخة المتصفح المحلية فقط.</p><form class="booking-form" id="bookingForm"><label>الاسم الكامل<input name="name" required maxlength="80" placeholder="اسم العميل"></label><label>رقم التواصل<input name="phone" required pattern="[0-9+ ]{8,20}" placeholder="05xxxxxxxx"></label><label>الخدمة<select name="service" required>${options}</select></label><label>التاريخ<input id="bookingDate" name="date" type="date" required></label><label>الوقت<select id="bookingTime" name="time" required></select></label><label class="wide">ملاحظات إضافية<textarea name="note" rows="3" maxlength="500"></textarea></label><button class="pill" type="submit" ${options?'':'disabled'}>إرسال طلب الموعد</button></form><p id="bookingMessage" role="status"></p></section>`}function sections(){const list=data.sections||[],block={hero:()=>`<section class="hero" id="home"><div><p>أهلاً بك في ${esc(f('businessName'))}</p><h1>${esc(f('tagline'))}</h1><p>${esc(f('description'))}</p><a class="pill" href="#${hasBookings()?'book':'contact'}">${hasBookings()?'احجز الآن':'تواصل معنا'}</a></div>${data.cover?`<img src="${data.cover}" alt="صورة النشاط">`:''}</section>`,items:()=>`<section class="section" id="services"><h2>${['store','food'].includes(f('category'))?'منتجاتنا':'خدماتنا'}</h2><div class="cards">${grid()}</div></section>`,gallery:()=>`<section class="section" id="gallery"><h2>معرض الصور</h2>${gallery()}</section>`,about:()=>`<section class="section"><h2>من نحن</h2><p>${esc(f('description'))}</p></section>`,contact:()=>`<section class="section" id="contact"><h2>تواصل معنا</h2>${contact()}</section>`,booking, map:()=>`<section class="section"><h2>موقعنا</h2>${mapView()}</section>`,inquiry:()=>'<section class="section"><h2>تواصل واستفسارات</h2><p>يرجى استخدام قنوات التواصل الظاهرة بالأسفل.</p></section>'};let unique=new Set();let rendered=list.filter(s=>{if(unique.has(s))return false;unique.add(s);return true}).map(k=>block[k]?.()||'').join('');if(!unique.has('gallery')&&data.gallery?.length)rendered+=block.gallery();if(!unique.has('contact'))rendered+=block.contact();if(!unique.has('booking')&&hasBookings())rendered+=block.booking();if(!unique.has('map')&&maps())rendered+=block.map();return rendered}function readBookings(){try{return JSON.parse(localStorage.getItem(BOOK)||'[]')}catch{return []}}function events(type,detail=''){if(new URLSearchParams(location.search).has('preview'))return;try{const arr=JSON.parse(localStorage.getItem(EVENT)||'[]');arr.push({type,detail,time:new Date().toISOString()});localStorage.setItem(EVENT,JSON.stringify(arr.slice(-500)))}catch{}}
function times(){const form=$('bookingForm');if(!form)return;const date=$('bookingDate'),select=$('bookingTime');date.min=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);const a=f('bookingStart')||'10:00',b=f('bookingEnd')||'20:00',toM=t=>{let [h,m]=t.split(':').map(Number);return h*60+m},start=toM(a),end=toM(b),busy=readBookings().filter(x=>x.date===date.value&&x.status!=='cancelled');select.innerHTML='<option value="">اختر الوقت</option>';for(let min=start;min+60<=end;min+=60){const label=String(Math.floor(min/60)).padStart(2,'0')+':'+String(min%60).padStart(2,'0');if(!busy.some(x=>x.time===label))select.innerHTML+=`<option value="${label}">${label}</option>`}if(select.options.length===1)select.innerHTML+='<option disabled>لا توجد مواعيد متاحة</option>'}function hookBooking(){const form=$('bookingForm');if(!form)return;$('bookingDate').addEventListener('change',times);times();form.addEventListener('submit',e=>{e.preventDefault();const v=new FormData(form);if(!v.get('date')||!v.get('time')||!v.get('name'))return;const today=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);if(String(v.get('date'))<today)return $('bookingMessage').textContent='اختر تاريخاً غير ماضٍ';const bookings=readBookings(),date=String(v.get('date')),time=String(v.get('time'));if(bookings.some(x=>x.date===date&&x.time===time&&x.status!=='cancelled')){times();return $('bookingMessage').textContent='هذا الموعد غير متاح، اختر وقتاً آخر.'}const index=Number(v.get('service'));bookings.push({id:'B'+Date.now()+Math.random().toString(36).slice(2,6),name:String(v.get('name')).slice(0,80),phone:String(v.get('phone')).slice(0,20),service:data.items?.[index]?.name||'',date,time,note:String(v.get('note')).slice(0,500),status:'pending'});try{localStorage.setItem(BOOK,JSON.stringify(bookings));$('bookingMessage').className='message';$('bookingMessage').textContent='تم تسجيل طلب الموعد محلياً! يمكنك رؤيته من لوحة صاحب النشاط في المحرر.';form.reset();times()}catch{$('bookingMessage').textContent='تعذر حفظ الحجز في المتصفح.'}})}
function render(){if(!data)return;const p=f('primary')||'#965f72',bg=f('background')||'#fcf5f2',ink=f('ink')||'#34262c',name=esc(f('businessName')||'اسم النشاط');$('siteRoot').innerHTML=`<div class="site" style="--primary:${esc(p)};--bg:${esc(bg)};--ink:${esc(ink)}"><header class="header"><div class="logo">${data.logo?`<img src="${data.logo}" alt="شعار النشاط">`:''}<span>${name}</span></div><nav class="nav">${navs.filter(([k])=>k!=='book'||hasBookings()).map(([k,v])=>`<a href="#${k==='home'?'home':k==='services'?'services':k==='gallery'?'gallery':k==='book'?'book':'contact'}">${v}</a>`).join('')}</nav></header><main>${sections()}</main><footer class="footer"><div><b>${name}</b><p>© ${new Date().getFullYear()} جميع الحقوق محفوظة</p></div><div><b>تابعنا وتواصل معنا</b>${contact()}</div><small>تم إنشاؤه بواسطة LaunchKit</small></footer></div>`;document.querySelectorAll('a[href^="https://wa.me"],a[href^="tel:"],a[href^="mailto:"]').forEach(a=>a.addEventListener('click',()=>events('contact',a.href)));hookBooking()}
function restore(){try{data=JSON.parse(localStorage.getItem(KEY)||'null')}catch{};if(!data){$('siteRoot').innerHTML='<div style="padding:3rem;font:18px Tahoma">لا يوجد موقع محفوظ بعد. افتح المحرر وأنشئ موقعك أولاً.</div>';return}render();events('view')};window.addEventListener('message',e=>{if(e.source!==window.parent||e.data?.type!=='LAUNCHKIT_STATE')return;try{data=JSON.parse(e.data.data);render()}catch{}});window.addEventListener('storage',e=>{if(e.key===KEY){restore()}});restore()})();
